// Entry is one row of an id table.
//
// Preset is the spelling the preset file uses for this id in its
// `entry/N/...` block -- "LFO 4", or "/p/part/t/1/p/p2/d". It is not
// the same vocabulary as Name, which is the engine's own symbol, and
// writing a preset needs both: the numeric matrix carries ids and the
// entry block carries these, and the two copies have to agree.
//
// Destination spellings always say `t/1` whatever timbre the row belongs
// to -- 1,138 of 2,552 in the corpus sit in timbre 2 or 3 and still say
// t/1 -- so this is a fixed label, not an address to be rewritten.
//
// Empty means no factory preset has ever used the id, so its spelling is
// unknown and a row using it cannot be written to the entry block.
type Entry struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Preset   string `json:"preset,omitempty"`
	Desc     string `json:"desc,omitempty"`
	Attested bool   `json:"attested"`
}

